local s=game.surfaces.aquilo local o={} local st={} for k,v in pairs(defines.entity_status) do st[v]=k end
for _,e in pairs(s.find_entities_filtered{name={'cryogenic-plant','pumpjack','heating-tower','roboport'},area={{-45,-75},{-18,-24}}}) do local r=e.type=='assembling-machine' and e.get_recipe() local fl='' for i=1,e.fluids_count do local fd=e.get_fluid(i) if fd then fl=fl..' '..fd.name..'='..math.floor(fd.amount) end end
local inv='' if e.type=='assembling-machine' then for _,it in pairs(e.get_inventory(defines.inventory.crafter_input).get_contents()) do inv=inv..' '..it.name..':'..it.count end inv=inv..' made '..e.products_finished end
o[#o+1]=e.name..' '..e.position.x..','..e.position.y..' d'..e.direction..' '..(r and r.name or '')..' '..(st[e.status] or '?')..(e.temperature and (' T'..math.floor(e.temperature)) or '')..fl..inv end
for _,p in pairs({{-35.5,-60.5},{-35.5,-43.5},{-35.5,-39.5},{-27.5,-35.5},{-20.5,-25.5}}) do local e=s.find_entities_filtered{name='pipe',position=p,radius=0.3}[1] if e then local fd=e.get_fluid(1) o[#o+1]='pipe '..p[1]..','..p[2]..' '..(fd and (fd.name..' '..math.floor(fd.amount)) or 'empty')..' '..st[e.status]..(e.frozen and ' FROZEN' or '') else o[#o+1]='no pipe '..p[1]..','..p[2] end end
local fr=0 local names={} for _,e in pairs(s.find_entities_filtered{force='player',area={{-45,-75},{-12,-22}}}) do if e.frozen then fr=fr+1 if #names<12 then names[#names+1]=e.name..'@'..e.position.x..','..e.position.y end end end o[#o+1]='frozen '..fr..' '..table.concat(names,' ')
for _,c in pairs(s.find_entities_filtered{type='logistic-container',area={{-45,-75},{-18,-24}}}) do local t={} for _,it in pairs(c.get_inventory(defines.inventory.chest).get_contents()) do t[#t+1]=it.name..'='..it.count end o[#o+1]=c.name..' '..c.position.x..','..c.position.y..' '..table.concat(t,' ') end
local net=s.find_logistic_network_by_position({-26,-27},'player') o[#o+1]='net at roboport: '..(net and ('cells '..#net.cells..' ice '..net.get_item_count('ice')..' lithium '..net.get_item_count('lithium')..' plate '..net.get_item_count('lithium-plate')..' packs '..net.get_item_count('cryogenic-science-pack')) or 'none')
local n=0 for _,e in pairs(s.find_entities_filtered{type='simple-entity'}) do if e.to_be_deconstructed() then n=n+1 end end o[#o+1]='icebergs still marked '..n
rcon.print(table.concat(o,'\n'))
